<script type="text/javascript">
    // Variables globales
    var refreshInterval = <?php echo $refresh_rate; ?> * 1000;
    var countdownInterval;
    var timeLeft = <?php echo $refresh_rate; ?>;

    // Función para reiniciar la cuenta regresiva
    function resetCountdown() {
        clearInterval(countdownInterval);
        timeLeft = <?php echo $refresh_rate; ?>;
        updateCountdown();
        
        countdownInterval = setInterval(function() {
            timeLeft--;
            updateCountdown();
            
            if (timeLeft <= 0) {
                //fetchData();
            }
        }, 1000);
    }

    // Actualizar el texto de cuenta atrás
    function updateCountdown() {
        //jQuery('#next-update').text('(próxima en ' + timeLeft + 's)');
    }

    function fetchData() {
        jQuery('#update-status').fadeIn();
        jQuery('.errors-container').hide();
        
        jQuery.ajax({
            url: '<?php echo url_for('email_sync/listAsync') ?>',
            data: jQuery('#<?php echo md5('frmfilteresync'); ?>').serialize(), //serializar.
            type: 'POST',
            contentType: 'application/x-www-form-urlencoded; charset=UTF-8',
            cache:false,
            processData: false,
            success: function(data) {
                updateDisplay(data);
                jQuery('#update-status').fadeOut();
            },
            error: function() {
                var errorHtml = `<div class="col-md-12"><div class="alert alert-danger"><strong>Opps!</strong> Ocurrio un error inesperado.</div></div>`;                
                jQuery('.errors-container').html(errorHtml);
                jQuery('.errors-container').show();
                jQuery('#update-status').fadeOut();
            }
        });

        jQuery('#update-status').fadeOut();
    }

    // Actualizar la visualización con los datos obtenidos
    function updateDisplay(data) {        
        // Actualizar el contenedor de unidades
        jQuery('#table-paginate').html(data);
        // Iniciar cuenta regresiva
        resetCountdown();
    }

    // Actualizar el texto de cuenta atrás
    function updateCountdown() {
        //jQuery('#next-update').text('(próxima en ' + timeLeft + 's)');
    }
    
    // Inicializar cuando el documento esté listo
    jQuery(document).ready(function() {
        // Cargar datos inicialmente
        fetchData();
        
        // Configurar actualización automática
        setInterval(fetchData, refreshInterval);
        
        // Botón de actualización manual
        jQuery('#refresh-now').click(function() {
            fetchData();
        });
    });
    
</script>